inline QString candidateLifecycle(BladeDiagnosis::RuleState state){using S=BladeDiagnosis::RuleState;switch(state){case S::Draft:return "草稿";case S::PendingValidation:return "待验证";case S::Validated:return "已验证（来源声明）";case S::Disabled:return "停用";}return {};}
